# Candidate bibliography specification (hand-written; expectations from memory, to be CHECKED).
# Fields: key, q (INSPIRE query), au (expected author surnames, in order), y (expected journal year),
#         j/v/p (expected journal, volume, first page/artid as INSPIRE abbreviates), grp (topic group), note.
S = []
def A(key, q, au, y, j=None, v=None, p=None, grp='', note=''):
    S.append(dict(key=key, q=q, au=au, y=y, j=j, v=v, p=p, grp=grp, note=note))
def J(key, j, v, p, au, y, grp, note):
    A(key, 'j "%s,%s,%s"' % (j, v, p), au, y, j, v, p, grp, note)
def X(key, arx, au, y, j, v, p, grp, note):
    A(key, 'arxiv:' + arx, au, y, j, v, p, grp, note)

